const now = new Date();

const sofiaDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Sofia',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(now);

const [year, month, day] = sofiaDate.split('-').map(Number);

const today = new Date(Date.UTC(year, month - 1, day));
const weekday = today.getUTCDay();

// Monday = 0, Sunday = 6
const daysSinceMonday = (weekday + 6) % 7;

const thisMonday = new Date(today);
thisMonday.setUTCDate(today.getUTCDate() - daysSinceMonday);

const previousMonday = new Date(thisMonday);
previousMonday.setUTCDate(thisMonday.getUTCDate() - 7);

const previousSunday = new Date(thisMonday);
previousSunday.setUTCDate(thisMonday.getUTCDate() - 1);

const formatDate = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    from_date: formatDate(previousMonday),
    to_date: formatDate(previousSunday),
    report_type: 'weekly_sales',
  },
}];

const items = $input.all();
const records = items.map(item => item.json);

const period = $('Calculate Previous Week').first().json;

for (const r of records) {
  if (
    typeof r.date !== 'string' ||
    !/^\d{4}-\d{2}-\d{2}$/.test(r.date) ||
    !Number.isInteger(r.orders) ||
    !Number.isInteger(r.units_sold) ||
    typeof r.revenue !== 'number' ||
    !Number.isFinite(r.revenue) ||
    r.orders < 0 ||
    r.units_sold < 0 ||
    r.revenue < 0
  ) {
    throw new Error(
      `Invalid Sales record: ${JSON.stringify(r)}`
    );
  }
}

const totals = records.reduce(
  (acc, r) => {
    acc.orders += r.orders;
    acc.units_sold += r.units_sold;
    acc.revenue += r.revenue;
    return acc;
  },
  { orders: 0, units_sold: 0, revenue: 0 }
);

const bestRevenueDay = records.reduce(
  (best, r) => !best || r.revenue > best.revenue ? r : best,
  null
);

const bestOrdersDay = records.reduce(
  (best, r) => !best || r.orders > best.orders ? r : best,
  null
);

return [{
  json: {
    report_type: 'weekly_sales',
    period_start: period.from_date,
    period_end: period.to_date,
    days_with_data: records.length,
    no_sales: records.length === 0 || totals.orders === 0,
    totals: {
      orders: totals.orders,
      units_sold: totals.units_sold,
      revenue: Number(totals.revenue.toFixed(2)),
    },
    best_revenue_day: bestRevenueDay
      ? {
          date: bestRevenueDay.date,
          revenue: bestRevenueDay.revenue,
        }
      : null,
    best_orders_day: bestOrdersDay
      ? {
          date: bestOrdersDay.date,
          orders: bestOrdersDay.orders,
        }
      : null,
    daily_sales: records,
  },
}];
